#include "ui/ui_language.hpp"
#include <QTextEdit>
#include <QVBoxLayout>
#include <QFileInfo>
#include <cassert>
#include <iostream>
int main(int argc,char** argv){QString root=argc>1?QString::fromLocal8Bit(argv[1]):QFileInfo(QString::fromLocal8Bit(argv[0])).absolutePath()+"/..";qputenv("QT_QPA_PLATFORM","offscreen");if(QFile::exists(root+"/platforms/qoffscreen.dll"))qputenv("QT_QPA_PLATFORM_PLUGIN_PATH",(root+"/platforms").toLocal8Bit());QApplication app(argc,argv);UiLanguage language;assert(language.load(root));QWidget window;auto layout=new QVBoxLayout(&window);auto label=new QLabel(QStringLiteral("Настройки"));auto page=new QLabel(QStringLiteral("Страница 2 из 3"));auto count=new QLabel(QStringLiteral("Найдено: 8 · по 24 на странице"));auto nickname=new QLineEdit(QStringLiteral("Настройки TEST"));nickname->setPlaceholderText(QStringLiteral("Ваша подпись по памяти, A–Z"));auto records=new QTextEdit;records->setReadOnly(true);records->setPlainText(QStringLiteral("Подписанный договор: Игрок TEST 100 000 ₽"));auto selector=new QComboBox;selector->addItem(QStringLiteral("Все города"),"uuid-city");for(auto w:std::vector<QWidget*>{label,page,count,nickname,records,selector})layout->addWidget(w);window.setWindowTitle(QStringLiteral("Настройки"));assert(language.setLanguage("en"));language.refresh();assert(label->text()=="Settings"&&window.windowTitle()=="Settings");assert(page->text()=="Page 2 of 3");assert(count->text()=="Found: 8 · 24 per page");assert(nickname->text()==QStringLiteral("Настройки TEST"));assert(nickname->placeholderText()=="Your signature from memory, A–Z");assert(records->toPlainText()==QStringLiteral("Подписанный договор: Игрок TEST 100 000 ₽"));assert(selector->currentData().toString()=="uuid-city"&&selector->currentText()=="All cities");label->setText(QStringLiteral("Гараж"));language.refresh();assert(label->text()=="Garage");assert(!language.setLanguage("invalid")&&language.language()=="en");assert(language.setLanguage("ru"));assert(label->text()==QStringLiteral("Гараж")&&page->text()==QStringLiteral("Страница 2 из 3")&&selector->currentData().toString()=="uuid-city");std::cout<<"PASS live RU/EN switching, dynamic labels/patterns, unchanged user text/documents/IDs, locale persistence boundary\n";}
